import{_ as a,c,o,ag as t}from"./chunks/framework.BpgFjFSJ.js";const r="/docs/static/image.FC44EOKE.png",m=JSON.parse('{"title":"React结构","description":"","frontmatter":{},"headers":[],"relativePath":"skill/react/principle/pack.md","filePath":"skill/react/principle/pack.md"}'),d={name:"skill/react/principle/pack.md"};function i(l,e,n,s,h,p){return o(),c("div",null,e[0]||(e[0]=[t('<h1 id="react结构" tabindex="-1">React结构 <a class="header-anchor" href="#react结构" aria-label="Permalink to &quot;React结构&quot;">​</a></h1><h2 id="基础包结构" tabindex="-1">基础包结构 <a class="header-anchor" href="#基础包结构" aria-label="Permalink to &quot;基础包结构&quot;">​</a></h2><p><a href="https://github.com/dabanheiji/react-study/tree/feature-v6" target="_blank" rel="noreferrer">学习React自己写的项目</a></p><p>React中基础包分为一下几个包</p><ul><li><code>react</code>：React基础包，只提供定义React组件的必要函数，一般来说要和渲染器一同使用，编写React代码的时候大部分是用的这个包的api</li><li><code>react-dom</code>：React渲染器之一，是React和web平台连接的桥梁，我们使用的入口函数 <code>ReactDOM.render()</code> 或者 <code>ReactDOM.createRoot().render()</code> 就是这个包提供的函数</li><li><code>react-reconciler</code>：这个包是React运行的核心包，用来协调 <code>react-dom</code>, <code>react</code>, <code>scheduler</code> 等包之间的通信，是React渲染的核心</li><li><code>scheduler</code>：这个包是调度机制的实现，控制由 <code>react-reconciler</code> 送入回调函数的执行时机，在编写 <code>react</code> 应用的代码时，同样不会调用此包提供的api</li></ul><h2 id="架构分层" tabindex="-1">架构分层 <a class="header-anchor" href="#架构分层" aria-label="Permalink to &quot;架构分层&quot;">​</a></h2><h3 id="接口层" tabindex="-1">接口层 <a class="header-anchor" href="#接口层" aria-label="Permalink to &quot;接口层&quot;">​</a></h3><p>在开发 <code>React</code> 应用时，使用的 api 大多来自 <code>react</code> 模块，我们改变渲染的基本操作有三个：</p><ol><li>class 组件的 <code>setState</code> 方法</li><li>函数组件的 <code>useState</code> 方法，底层是 <code>dispatchAction</code> 方法</li><li>改变 <code>context</code> 的值，这个基本上需要结合 1 和 2 中的方法一起使用</li></ol><h3 id="内核层" tabindex="-1">内核层 <a class="header-anchor" href="#内核层" aria-label="Permalink to &quot;内核层&quot;">​</a></h3><h4 id="调度器" tabindex="-1">调度器 <a class="header-anchor" href="#调度器" aria-label="Permalink to &quot;调度器&quot;">​</a></h4><p>调度器就是 <code>scheduler</code> 包，这个包只起到一个作用就是回调，主要是把 <code>react-reconciler</code> 提供的回调函数包装到一个任务对象中，在内部维护一个任务队列，按照优先级去回调任务，直到任务队列清空。</p><h4 id="构造器" tabindex="-1">构造器 <a class="header-anchor" href="#构造器" aria-label="Permalink to &quot;构造器&quot;">​</a></h4><p>构造器就是 <code>react-reconciler</code> 包，接收 <code>react-dom</code> 包的初次渲染和 <code>react</code> 包中发起的更新请求，将 fiber 树的构造过程包装在一个回调函数中，并将这些回调函数传入 <code>scheduler</code> 包中，由调度器去执行。</p><h4 id="渲染层" tabindex="-1">渲染层 <a class="header-anchor" href="#渲染层" aria-label="Permalink to &quot;渲染层&quot;">​</a></h4><p>渲染层就是 <code>react-dom</code> 包，这个包的主要作用是引导 <code>react</code> 应用的启动，以及实现 <code>HostConfig</code> 接口，用于 <code>react-reconciler</code> 包的调用。</p><p>图解</p><p><img src="'+r+'" alt=""></p>',18)]))}const _=a(d,[["render",i]]);export{m as __pageData,_ as default};
